import React, { Component } from 'react';
import { Tooltip, Modal, Button, Avatar } from 'antd';
import { connect } from 'react-redux';
import { updatePrivilege } from 'redux/actions/common';
import { capitalize } from 'lodash';
import RandomColor from './randomColor';

class InsufficientPrivilege extends Component {
  constructor(props) {
    super(props);

    this.handleCancel = this.handleCancel.bind(this);
    this.handleOk = this.handleOk.bind(this);
  }

  handleOk() {
    this.props.updatePrivilege();
  }

  handleCancel() {
    this.props.updatePrivilege();
  }

  render() {
    return (
      <Modal
        visible={this.props.privilege.status}
        // title="Insufficient Privilege"
        onOk={this.handleOk}
        onCancel={this.handleCancel}
        className="basic-info-modal"
        footer={[
          <Button
            key="back"
            onClick={this.handleCancel}
            style={{ display: 'none' }}
          >
            Return
          </Button>,
          <Button key="submit" type="primary" onClick={this.handleOk}>
            Ok
          </Button>,
        ]}
      >
        <h2>Insufficient Privilege</h2>
        <h3>
          You do not have required privilege for this action. <br /> Please
          contact any of the team member below.{' '}
        </h3>
        {this.props.privilege.data ? (
          this.props.privilege.data.team.length < 4 ? (
            <div className="user-avatars">
              {' '}
              {this.props.privilege.data.team.map((obj, i) =>
                obj.picture ? (
                  <a key={i}>
                    <Tooltip
                      overlayStyle={{ zIndex: 999999999 }}
                      placement="top"
                      title={obj.name}
                      className="privilage"
                    >
                      <Avatar src={obj.picture} size="large" />
                    </Tooltip>
                  </a>
                ) : (
                  <a key={i}>
                    <Tooltip
                      placement="top"
                      overlayStyle={{ zIndex: 999999999 }}
                      title={obj.name}
                    >
                      <Avatar
                        size="large"
                        style={{
                          color: '#FFFFFF',
                          backgroundColor: obj.name
                            ? RandomColor(obj.name.trim())
                            : '',
                        }}
                      >
                        {obj.name ? capitalize(obj.name.trim().charAt(0)) : ''}
                      </Avatar>
                    </Tooltip>
                  </a>
                )
              )}
            </div>
          ) : (
            <div className="user-avatars">
              {this.props.privilege.data.team[0].picture ? (
                <Tooltip
                  overlayStyle={{ zIndex: 999999999 }}
                  placement="top"
                  title={this.props.privilege.data.team[0].name}
                >
                  <a />{' '}
                  <Avatar
                    src={this.props.privilege.data.team[0].picture}
                    size="large"
                  />
                </Tooltip>
              ) : (
                <Tooltip
                  overlayStyle={{ zIndex: 999999999 }}
                  placement="top"
                  title={this.props.privilege.data.team[0].name}
                >
                  <Avatar
                    size="large"
                    style={{
                      color: '#FFFFFF',
                      backgroundColor: this.props.privilege.data.team[0].name
                        ? RandomColor(
                            this.props.privilege.data.team[0].name.trim()
                          )
                        : '',
                    }}
                  >
                    {this.props.privilege.data.team[0].name
                      ? capitalize(
                          this.props.privilege.data.team[0].name
                            .trim()
                            .charAt(0)
                        )
                      : ''}
                  </Avatar>
                </Tooltip>
              )}
              {this.props.privilege.data.team[1].picture ? (
                <Tooltip
                  overlayStyle={{ zIndex: 999999999 }}
                  placement="top"
                  title={this.props.privilege.data.team[1].name}
                >
                  <Avatar
                    src={this.props.privilege.data.team[1].picture}
                    size="large"
                  />
                </Tooltip>
              ) : (
                <Avatar
                  size="large"
                  style={{
                    color: '#FFFFFF',
                    backgroundColor: this.props.privilege.data.team[1].name
                      ? RandomColor(
                          this.props.privilege.data.team[1].name.trim()
                        )
                      : '',
                  }}
                >
                  {this.props.privilege.data.team[1].name
                    ? capitalize(
                        this.props.privilege.data.team[1].name.trim().charAt(0)
                      )
                    : ''}
                </Avatar>
              )}
              {this.props.privilege.data.team[2].picture ? (
                <Tooltip
                  overlayStyle={{ zIndex: 999999999 }}
                  placement="top"
                  title={this.props.privilege.data.team[2].name}
                >
                  {' '}
                  <Avatar
                    src={this.props.privilege.data.team[2].picture}
                    size="large"
                  />
                </Tooltip>
              ) : (
                <Tooltip
                  overlayStyle={{ zIndex: 999999999 }}
                  placement="top"
                  title={this.props.privilege.data.team[2].name}
                >
                  <Avatar
                    size="large"
                    style={{
                      color: '#FFFFFF',
                      backgroundColor: this.props.privilege.data.team[2].name
                        ? RandomColor(
                            this.props.privilege.data.team[2].name.trim()
                          )
                        : '',
                    }}
                  >
                    {this.props.privilege.data.team[2].name
                      ? capitalize(
                          this.props.privilege.data.team[2].name
                            .trim()
                            .charAt(0)
                        )
                      : ''}
                  </Avatar>
                </Tooltip>
              )}
              <a href="#" className="see-more">
                +{this.props.privilege.data.team.length - 3}
              </a>
            </div>
          )
        ) : (
          ''
        )}
      </Modal>
    );
  }
}

function mapStateToProps(state) {
  return {
    privilege: state.privilegeReducer,
  };
}

export default connect(mapStateToProps, { updatePrivilege })(
  InsufficientPrivilege
);
